WITH kids AS (
  SELECT n.id, n.name, n.leveltype,
         if(n.leveltype = 'TOPIC', n.parentid, p.parentid) AS chid,
         if(n.leveltype = 'SUB_TOPIC', p.name, '') AS topic_name
  FROM masked_vedantu_lms_vedantumoodle.topictree n
  LEFT JOIN masked_vedantu_lms_vedantumoodle.topictree p ON p.id = n.parentid
  WHERE n.leveltype IN ('TOPIC','SUB_TOPIC')
)
SELECT leveltype, count() AS n, countDistinct(chid) AS chapters
FROM kids WHERE chid IN ('67d2a00d1d8bb4fb6545d480','67d2a00e1d8bb4fb6545d484','67d2a00a1d8bb4fb6545d479','67d2a0141d8bb4fb6545d498','67d2a0161d8bb4fb6545d49e','69b3aa7a8141fac06f954e14','67d2a0361d8bb4fb6545d4f5','69b3aa798141fac06f954e12','69b3ab328141fac06f954ed6','69b3aaee8141fac06f954e8c','69b3ab298141fac06f954ecb','69b3ab068141fac06f954ea5','69b3ab138141fac06f954eb2','69b3aad78141fac06f954e73','69b3aacd8141fac06f954e68','69b3ab4e8141fac06f954efe','69b3aae08141fac06f954e7e','69b3aac18141fac06f954e5c','69b3ab448141fac06f954eef','69b3ab388141fac06f954edf','69b3aafa8141fac06f954e98','67d29ff01d8bb4fb6545d434','67d2a0ac1d8bb4fb6545d61b','67d2a0861d8bb4fb6545d5b9','67d2a0581d8bb4fb6545d547','67d2a0a91d8bb4fb6545d612','67d2a0701d8bb4fb6545d57f','67d2a0781d8bb4fb6545d593','67d2a0971d8bb4fb6545d5e5','67d2a05e1d8bb4fb6545d556','67d2a07f1d8bb4fb6545d5a6','67c6f09eb447f95a53c5bf50','67c6f033b447f95a53c5be82','67c6f103b447f95a53c5c01a','67c6f10bb447f95a53c5c02a','67c6f0c9b447f95a53c5bfa5','67c6f0eeb447f95a53c5bff3','67c6f0ebb447f95a53c5bfed','67c6f0e1b447f95a53c5bfd6','67c6effbb447f95a53c5be3a','67c6f008b447f95a53c5be4c','67c6efbdb447f95a53c5bdd8','67c6efb1b447f95a53c5bdc4','67c6efcab447f95a53c5bded','67c6eff1b447f95a53c5be2c','67c6efedb447f95a53c5be24','67c6efffb447f95a53c5be40','67c6efe4b447f95a53c5be16','67c6efd3b447f95a53c5bdfc','67c6efb5b447f95a53c5bdcb','67c6efdcb447f95a53c5be0d','67c6efa3b447f95a53c5bdb1','67c6ef97b447f95a53c5bda3','67c6efc5b447f95a53c5bde6','67c6efabb447f95a53c5bdbc','67c6f00fb447f95a53c5be56','67c6ef40b447f95a53c5bd1f','67c6eee9b447f95a53c5bc8b','67c6eed1b447f95a53c5bc62','67c6eef7b447f95a53c5bca1','67c6eecfb447f95a53c5bc5d','67c6eec9b447f95a53c5bc54','67c6ef69b447f95a53c5bd61','67c6eee2b447f95a53c5bc7e','67c6eedbb447f95a53c5bc71','67d1649e32cfbfe2a5bc6c23','67d164a432cfbfe2a5bc6c2a','67d164a832cfbfe2a5bc6c2e','67c6fbc35ba56eb26df66039','69b2b3c2be7def4d344878b2','69b2b411be7def4d344878d8','69b2b42abe7def4d344878e4','67c6fd2921a22fe660b13dae','67c